css:
.article {
  max-width: 520px;
  padding: 24px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 18px;
  line-height: 1.6;
  color: #27272a;
}

.lead::first-letter {
  float: left;
  margin: 6px 10px 0 0;
  font-size: 64px;
  line-height: 0.85;
  font-weight: 700;
  color: #c2410c;
}

.lead::first-line {
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.body {
  margin-bottom: 0;
}
